import{_ as e,o as s,c as n,a2 as t}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"TUI 指南（终端用户界面）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/tui-guide.md","filePath":"zh/manual/tui-guide.md"}'),i={name:"zh/manual/tui-guide.md"};function l(o,a,p,c,d,r){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="tui-指南-终端用户界面" tabindex="-1">TUI 指南（终端用户界面） <a class="header-anchor" href="#tui-指南-终端用户界面" aria-label="Permalink to &quot;TUI 指南（终端用户界面）&quot;">​</a></h1><p>TUI 层（<code>tui/</code>）是一个运行在帧缓冲上的窗口系统： 桌面、任务栏、菜单、表单、面板、文本编辑器和系统应用 全部通过键盘驱动。</p><h2 id="启动它" tabindex="-1">启动它 <a class="header-anchor" href="#启动它" aria-label="Permalink to &quot;启动它&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; tui</span></span></code></pre></div><p>桌面会接管整个屏幕。（在 QEMU 中，去掉 <code>-display none</code> 参数， 使用 SDL/GTK 窗口以便查看；串口控制台会继续在后台运行。）</p><h2 id="桌面" tabindex="-1">桌面 <a class="header-anchor" href="#桌面" aria-label="Permalink to &quot;桌面&quot;">​</a></h2><ul><li>带有启动器的任务栏。</li><li>包含标准组件集的窗口：菜单、表单、文本区域、面板。</li><li>捆绑的应用包括系统监控器（进程、内存）、 文件、一个 TUI 编辑器、网络状态和系统信息。</li></ul><h2 id="键盘模型" tabindex="-1">键盘模型 <a class="header-anchor" href="#键盘模型" aria-label="Permalink to &quot;键盘模型&quot;">​</a></h2><ul><li>方向键 / Tab 键导航；Enter 激活；Esc 返回。</li><li>编辑器使用与 Shell 行编辑器相同的行规。</li><li><code>tui</code> 应用既可通过桌面启动器访问，也可作为 单独命令运行 - 参见命令索引中的 <a href="./commands/">TUI 域</a>。</li></ul><h2 id="tui-命令" tabindex="-1">TUI 命令 <a class="header-anchor" href="#tui-命令" aria-label="Permalink to &quot;TUI 命令&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; tui              (enter the desktop)</span></span>
<span class="line"><span>oc&gt; tui-test         (the TUI regression suite)</span></span>
<span class="line"><span>oc&gt; tui-hw           (TUI hardware/render diagnostics)</span></span>
<span class="line"><span>oc&gt; tui-net          (network status app)</span></span>
<span class="line"><span>oc&gt; tui-sysinfo      (system information app)</span></span>
<span class="line"><span>oc&gt; tui-time         (clock/time sources panel)</span></span>
<span class="line"><span>oc&gt; tui-sys          (system monitor)</span></span>
<span class="line"><span>oc&gt; tui-drv          (driver inventory)</span></span>
<span class="line"><span>oc&gt; tui-ext          (extension surface status)</span></span></code></pre></div><h2 id="中文控制台与-tui" tabindex="-1">中文控制台与 TUI <a class="header-anchor" href="#中文控制台与-tui" aria-label="Permalink to &quot;中文控制台与 TUI&quot;">​</a></h2><p>中文层（<code>chinese</code> 命令）将控制台切换为 16x16 CJK 字体并采用 GB 编码和拼音输入法， 同时提供硬件/网络/系统信息 TUI 应用的中文版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; chinese          (status of font/encoding/render/ime)</span></span>
<span class="line"><span>oc&gt; ime -i           (interactive pinyin input line)</span></span>
<span class="line"><span>oc&gt; lang             (language console switch)</span></span></code></pre></div><p>系统字符串按约定保持 ASCII；中文层渲染用户内容 - 参见 <a href="./chinese-console.html">chinese-console</a>。</p><h2 id="扩展接口面" tabindex="-1">扩展接口面 <a class="header-anchor" href="#扩展接口面" aria-label="Permalink to &quot;扩展接口面&quot;">​</a></h2><p>L1 模块可通过 <code>tui/tui_ext.h</code>（37 个可调用声明 - 窗口、菜单、表单、面板、文本） 创建 TUI 窗口和组件。TUI 命令桥本身就是参考实现： 它通过 L1 API 遍历 Shell 命令表并将其渲染为启动器。扩展指南： <a href="./../l1/tui-ext.html">../l1/tui-ext.md</a>。</p><h2 id="不构建-tui-进行构建" tabindex="-1">不构建 TUI 进行构建 <a class="header-anchor" href="#不构建-tui-进行构建" aria-label="Permalink to &quot;不构建 TUI 进行构建&quot;">​</a></h2><p><code>make CONFIG_TUI=n</code> 会从镜像中移除 TUI（同时 <code>CONFIG_CHINESE=n</code> 会移除中文层）， 启动后注册 216 个命令（233 - 17）。这个非完整路径是具有 ASCII 等价路由的真实代码， 而非被删除的功能。参见 <a href="./../dev/build.html">../dev/build.md</a>。</p>`,19)])])}const m=e(i,[["render",l]]);export{u as __pageData,m as default};
